# owner: platform
"""Contact sheet for substitute teachers."""

from rosterkit.errors import ProjectError


def _check(students):
    if not students:
        raise ProjectError("no students given")
    for student in students:
        if not student.email:
            name = student.display_name
            raise ProjectError(f"no email for {name}")


def _pad(cells, widths):
    padded = (c.ljust(w) for c, w in zip(cells, widths))
    return "  ".join(padded).rstrip()


# ---
def contact_rows(students):
    _check(students)
    ordered = sorted(students, key=lambda s: s.display_name)
    cells = [
        (s.display_name, s.section, s.email)
        for s in ordered
    ]
    widths = [max(map(len, col)) for col in zip(*cells)]
    return [_pad(row, widths) for row in cells]

